    calibrationMetrics: {
      type: Type.OBJECT,
      properties: {
        rosterStability: { type: Type.NUMBER },
        marketAlignment: { type: Type.NUMBER },
        situationalCertainty: { type: Type.NUMBER },
        varianceRisk: { type: Type.STRING, enum: ["Minimal", "Moderate", "High"] }
      },
      required: ["rosterStability", "marketAlignment", "situationalCertainty", "varianceRisk"]
    },
    simulatedScenarios: {
      type: Type.OBJECT,
      properties: {
        total: { type: Type.INTEGER },
        wins: { type: Type.INTEGER },
        avgMargin: { type: Type.STRING }
      },
      required: ["total", "wins", "avgMargin"]
    },
    injuryReport: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          player: { type: Type.STRING },
          status: { type: Type.STRING },
          role: { type: Type.STRING, description: "e.g. 'Starting PG', 'Edge Rusher'" },
          impactScore: { type: Type.INTEGER },
          analysis: { type: Type.STRING }
        },
        required: ["player", "status", "role", "impactScore"]
      }
    },
    advancedAnalytics: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          label: { type: Type.STRING },
          value: { type: Type.STRING },
          percentile: { type: Type.NUMBER },
          description: { type: Type.STRING }
        },
        required: ["label", "value", "percentile", "description"]
      }
    },
    situationalIntelligence: {
      type: Type.OBJECT,
      properties: {
        motivationLevel: { type: Type.STRING, enum: ["Elite (Must-Win)", "High (Playoff Push)", "Moderate (Regular Season)", "Low (Resting/Tanking)"] },
        playoffContext: { type: Type.STRING },
        isHighStakes: { type: Type.BOOLEAN },
        leverageAnalysis: { type: Type.STRING },
        expectedGameScript: { type: Type.STRING, enum: ["High-Pace/Competitive", "Low-Pace/Blowout-Risk", "Defensive-Grind"] },
        weatherImpact: { type: Type.STRING },
        venueFactor: { type: Type.STRING }
      },
      required: ["motivationLevel", "playoffContext", "isHighStakes", "leverageAnalysis", "expectedGameScript"]
    },
    eliteSignal179: { type: Type.BOOLEAN },
    analysis: { type: Type.STRING },
    matchupHighlight: { type: Type.STRING },
    gameScript: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          phase: { type: Type.STRING },
          description: { type: Type.STRING }
        },
        required: ["phase", "description"]
      }
    },
    statComparison: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          statName: { type: Type.STRING },
          homeValue: { type: Type.STRING },
          awayValue: { type: Type.STRING },
          advantage: { type: Type.STRING, enum: ["Home", "Away", "Push"] }
        }
      }
    },
    trends: { type: Type.ARRAY, items: { type: Type.STRING } },
    odds: {
      type: Type.OBJECT,
      properties: {
        winner: { type: Type.STRING },
        loser: { type: Type.STRING }
      }
    },
    props: {
        type: Type.ARRAY,
        items: {
            type: Type.OBJECT,
            properties: {
                player: { type: Type.STRING },
                line: { type: Type.STRING },
                stat: { type: Type.STRING },
                type: { type: Type.STRING, enum: ["MORE", "LESS"] },
                odds: { type: Type.STRING },
                probability: { type: Type.STRING },
                isElite179: { type: Type.BOOLEAN },
                ev: { type: Type.NUMBER },
                matchupEdge: { type: Type.STRING, description: "Specific technical reason for this prop edge (e.g. 'Weak interior defense vs player playstyle')." },
                situationalNote: { type: Type.STRING },
                performanceHistory: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      date: { type: Type.STRING },
                      opponent: { type: Type.STRING },
                      actualValue: { type: Type.STRING },
                      hit: { type: Type.BOOLEAN }
                    },
                    required: ["date", "opponent", "actualValue", "hit"]
                  }
                },
                lineComparison: {
                  type: Type.ARRAY,
                  items: {
                    type: Type.OBJECT,
                    properties: {
                      book: { type: Type.STRING },
                      line: { type: Type.STRING },
                      odds: { type: Type.STRING }
                    },
                    required: ["book", "line", "odds"]
                  }
                },
                analysis: { type: Type.STRING }
            },
            required: ["player", "line", "stat", "type", "probability", "analysis", "performanceHistory", "lineComparison", "matchupEdge"]
        }
    }
  },
  required: ["winner", "loser", "confidence", "confidenceScore", "confidenceReasoning", "calibrationMetrics", "simulatedScenarios", "situationalIntelligence", "eliteSignal179", "analysis", "gameScript", "statComparison", "injuryReport", "odds", "props", "trends", "advancedAnalytics"]
};

export const getSchedule = async (sport: string): Promise<Game[]> => {
  const ai = getAI();
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  const prompt = `Search for ${sport} games occurring TODAY, ${today}. 
  CRITICAL: Cross-reference current active rosters. Are there any late-breaking scratches or major bench updates?
  Include playoff context and situational urgency.
  Return STRICT JSON: { "games": [{ "id": "string", "homeTeam": "string", "awayTeam": "string", "league": "${sport}", "time": "string", "date": "Today", "status": "Scheduled|Live|Finished", "isMustWin": boolean, "playoffImplications": "string", "keyRosterNotes": "string (e.g. 'Star QB Questionable', 'Full Strength')", "odds": { "spread": "string", "moneyline": "string", "total": "string" } }] }`;

  const configWithSearch = { 
    tools: [{ googleSearch: {} }],
    temperature: 0.1,
    responseMimeType: 'application/json'
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: configWithSearch as any
    });
    const data = JSON.parse(response.text || '{}');
    return data.games || [];
  } catch (error: any) {
    return [];
  }
};

import React, { useState, useCallback, useEffect } from 'react';
import { Header } from './components/Header';
import { SportSelector } from './components/SportSelector';
import { GameSchedule } from './components/GameSchedule';
import { PredictionDisplay } from './components/PredictionDisplay';
import { Loader } from './components/Loader';
import { Footer } from './components/Footer';
import { SettingsModal } from './components/SettingsModal';
import { TokenomicsModal } from './components/TokenomicsModal';
import { ChatInterface } from './components/ChatInterface';
import { SuggestionChips } from './components/SuggestionChips';
import { PickSlip } from './components/PickSlip';
import { PerformanceSidebar } from './components/PerformanceSidebar';
import { VaultView } from './components/VaultView';
import { GoogleGenAI } from "@google/genai";
import { predictionSchema } from './services/geminiService';
import type { Prediction, UserSettings, ChatMessage, Game, PropBet, SavedMatchup } from './types';
import type { Chat } from '@google/genai';

const App: React.FC = () => {
  const [settings, setSettings] = useState<UserSettings>(() => {
    try {
      const storedSettings = localStorage.getItem('prognosSettings');
      if (storedSettings) return JSON.parse(storedSettings);
    } catch (e) { console.error(e); }
    return { preferredSport: 'NFL', defaultConfidenceFilter: 'All', oddsFormat: 'American' };
  });

  const [selectedSport, setSelectedSport] = useState<string>(settings.preferredSport);
  const [selectedGame, setSelectedGame] = useState<Game | null>(null);
  const [prediction, setPrediction] = useState<Prediction | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isReplying, setIsReplying] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);
  const [isTokenModalOpen, setIsTokenModalOpen] = useState<boolean>(false);
  const [isHistorySidebarOpen, setIsHistorySidebarOpen] = useState<boolean>(true);
  const [chat, setChat] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [showSuggestions, setShowSuggestions] = useState<boolean>(false);
  const [pickSlip, setPickSlip] = useState<PropBet[]>([]);
  const [view, setView] = useState<'Feed' | 'Vault'>('Feed');
  const [vault, setVault] = useState<SavedMatchup[]>(() => {
    const saved = localStorage.getItem('prognosVault');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => { setSelectedSport(settings.preferredSport); }, [settings.preferredSport]);
  useEffect(() => {
    setSelectedGame(null);
    setPrediction(null);
    setMessages([]);
    setChat(null);
  }, [selectedSport]);

  const addToVault = useCallback((newPrediction: Prediction, game: Game) => {
    if (!newPrediction.props) return;
    const sortedProps = [...newPrediction.props].sort((a, b) => (parseInt(b.probability) || 0) - (parseInt(a.probability) || 0));
    const entry: SavedMatchup = {
      id: `${game.id}-${Date.now()}`,
      timestamp: Date.now(),
      homeTeam: game.homeTeam,
      awayTeam: game.awayTeam,
      winner: newPrediction.winner,
      confidence: newPrediction.confidence,
      confidenceScore: newPrediction.confidenceScore,
      elitePair: sortedProps.slice(0, 2)
    };
    setVault(prev => [entry, ...prev.filter(v => !v.id.startsWith(game.id))].slice(0, 4));
  }, []);

  const handlePredict = useCallback(async (isRetry = false) => {
    if (!selectedGame) return;
    setIsLoading(true);
    setError(null);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const config: any = {
        systemInstruction: `You are the PRO-N-OS 179-Elite Accuracy Engine. Your primary objective is to identify high-probability outcomes and sharp prop picks with mathematical precision.

        PHASE 1: INDIVIDUAL MATCHUP DELTA (IMD)
        - For every prop bet generated, you MUST analyze the specific player vs defender matchup. 
        - Look at height/weight deltas, speed/velocity metrics, and historical performance against that specific opponent or scheme.
        - Only suggest props where the "True Probability" exceeds 65%.

        PHASE 2: ROSTER INTEGRITY SCRUB
        - Scrutinize minutes/usage. If a star player's usage is expected to drop due to injury, blowout risk, or rest, adjust all associated props DOWN.
        - Audit late-breaking status. Use Google Search to find tweets or news from within the last 60 minutes.

        PHASE 3: MARKET VALUE SCAN
        - Compare your generated line vs current Vegas/Sharp lines. 
        - Highlight "Positive EV" opportunities where the model sees a significant edge that the market is missing.

        PHASE 4: SHARP REASONING
        - Assign "Elite Signal" (isElite179: true) ONLY to picks that pass all three checks: 90%+ Roster Stability, Elite Matchup Edge, and Historical Consistency (Hit 4/5 of last 5).
        - Provide a "matchupEdge" for every prop explaining the specific technical advantage.

        OUTPUT: Return strict JSON conforming to the predictionSchema. Quality over quantity.`,
        responseSchema: predictionSchema,
        responseMimeType: 'application/json',
      };

      if (!isRetry) config.tools = [{ googleSearch: {} }];

      const newChat = ai.chats.create({ model: 'gemini-3-pro-preview', config });
      const response = await newChat.sendMessage({ 
        message: `PERFORM HIGH-FIDELITY SIMULATION: ${selectedGame.homeTeam} vs ${selectedGame.awayTeam}. Focus on Prop Accuracy and Individual Matchup Deltas. Identify the 3 sharpest props available based on current data streams.` 
      });

      const parsed = JSON.parse(response.text);
      setPrediction(parsed);
      addToVault(parsed, selectedGame);
      setMessages([{ role: 'model', content: parsed }]);
      setChat(newChat);
      setShowSuggestions(true);
    } catch (err: any) {
      setError("Deep sync failed. Market variance or roster data stream is currently unstable.");
    } finally {
      setIsLoading(false);
    }
  }, [selectedGame, addToVault]);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!chat) return;
    setMessages(prev => [...prev, { role: 'user', content: text }]);
    setIsReplying(true);
    try {
        const response = await chat.sendMessage({ message: text });
        setMessages(prev => [...prev, { role: 'model', content: response.text || "Data stream interrupted." }]);
    } catch (e) {
        setMessages(prev => [...prev, { role: 'model', content: "Deep engine sync lost." }]);
    } finally {
        setIsReplying(false);
    }
  }, [chat]);

  return (
    <div className="min-h-screen bg-black text-white font-sans selection:bg-amber-500/30 overflow-x-hidden">
      <Header 
        onOpenSettings={() => setIsSettingsOpen(true)} 
        onOpenToken={() => setIsTokenModalOpen(true)} 
        currentView={view}
        onSetView={setView}
        vaultCount={vault.length}
      />
      <main className={`container mx-auto px-4 py-6 max-w-4xl transition-all duration-500 ${isHistorySidebarOpen && pickSlip.length > 0 ? 'md:pr-[300px]' : ''}`}>
        {view === 'Vault' ? (
            <VaultView vault={vault} onClear={() => setVault([])} onRemove={(id) => setVault(v => v.filter(x => x.id !== id))} />
        ) : (
            <>
                {error && <div className="bg-red-900/40 border border-red-500/30 text-red-100 px-4 py-3 rounded-xl mb-6 flex justify-between items-center">{error}</div>}
                {!prediction && messages.length === 0 && !isLoading ? (
                    <div className="space-y-8">
                        <SportSelector selectedSport={selectedSport} onSelectSport={setSelectedSport} />
                        <GameSchedule sport={selectedSport} selectedGame={selectedGame} onSelectGame={setSelectedGame} />
                        {selectedGame && (
                            <div className="fixed bottom-10 left-0 right-0 p-4 flex justify-center z-20">
                                <button onClick={() => handlePredict()} className="bg-gradient-to-r from-amber-500 to-orange-600 text-black font-black text-lg py-5 px-14 rounded-full shadow-[0_0_50px_rgba(245,158,11,0.4)] transform hover:scale-105 transition-all flex items-center gap-3">
                                    <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                                    SYNC ROSTERS & SIMULATE
                                </button>
                            </div>
                        )}
                    </div>
                ) : isLoading ? <Loader /> : (
                    <div className="space-y-4">
                        <button onClick={() => { setPrediction(null); setMessages([]); setChat(null); }} className="text-zinc-500 hover:text-white mb-2 text-[10px] font-black uppercase tracking-widest flex items-center gap-2">
                             <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
                             Live Feed
                        </button>
                        <ChatInterface messages={messages} isReplying={isReplying} onSendMessage={handleSendMessage} oddsFormat={settings.oddsFormat} pickSlip={pickSlip} onTogglePick={(p) => setPickSlip(prev => prev.includes(p) ? prev.filter(x => x !== p) : [...prev, p])} />
                        {showSuggestions && prediction && <SuggestionChips prediction={prediction} onSelect={handleSendMessage} />}
                    </div>
                )}
            </>
        )}
      </main>
      <PerformanceSidebar isOpen={isHistorySidebarOpen && pickSlip.length > 0} activePicks={pickSlip} onClose={() => setIsHistorySidebarOpen(false)} />
      <PickSlip picks={pickSlip} onRemove={(p) => setPickSlip(prev => prev.filter(x => x !== p))} onAnalyze={() => { handleSendMessage("Analyze my slip risk based on current roster deltas and situational motivation. Is there a sharp edge here?"); setIsHistorySidebarOpen(true); }} />
      <Footer />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} currentSettings={settings} onSave={(s) => { setSettings(s); setIsSettingsOpen(false); }} />
      <TokenomicsModal isOpen={isTokenModalOpen} onClose={() => setIsTokenModalOpen(false)} />
    </div>
  );
};

export default App;

import type React from 'react';

export type ConfidenceLevel = 'High' | 'Medium' | 'Low';
export type MotivationLevel = 'Elite (Must-Win)' | 'High (Playoff Push)' | 'Moderate (Regular Season)' | 'Low (Resting/Tanking)';

export interface PerformanceGame {
  date: string;
  opponent: string;
  actualValue: string;
  hit: boolean;
}

export interface BookLine {
  book: string;
  line: string;
  odds: string;
}

export interface MatchupMetric {
  rank: string;
  category: string;
  strength: 'Weak' | 'Strong' | 'Neutral';
}

export interface Injury {
  player: string;
  status: string;
  impactScore: number;
  role: string;
  analysis?: string;
}

export interface AdvancedMetric {
  label: string;
  value: string;
  percentile: number;
  description: string;
}

export interface CalibrationMetrics {
  rosterStability: number; // 0-100
  marketAlignment: number; // 0-100
  situationalCertainty: number; // 0-100
  varianceRisk: 'Minimal' | 'Moderate' | 'High';
}

export interface SituationalIntelligence {
  motivationLevel: MotivationLevel;
  playoffContext: string;
  isHighStakes: boolean;
  leverageAnalysis: string;
  expectedGameScript: 'High-Pace/Competitive' | 'Low-Pace/Blowout-Risk' | 'Defensive-Grind';
  weatherImpact?: string;
  venueFactor?: string;
}

export interface PropBet {
  player: string;
  bet: string;
  line: string;
  stat: string;
  type: 'MORE' | 'LESS';
  odds: string;
  probability: string;
  ev?: number;
  isElite179?: boolean;
  matchupEdge?: string;
  analysis?: string;
  situationalNote?: string;
  matchupMetric?: MatchupMetric;
  lineComparison?: BookLine[];
  performanceHistory?: PerformanceGame[];
}

export interface SavedMatchup {
    id: string;
    timestamp: number;
    homeTeam: string;
    awayTeam: string;
    winner: string;
    confidence: ConfidenceLevel;
    confidenceScore: number;
    elitePair: PropBet[];
}

export interface GameOdds {
  spread?: string;
  moneyline?: string;
  total?: string;
}

export interface StatComparison {
  statName: string;
  homeValue: string;
  awayValue: string;
  advantage: 'Home' | 'Away' | 'Push';
}

export interface GameScriptPhase {
  phase: string;
  description: string;
}

export interface Prediction {
  winner: string;
  loser: string;
  confidence: ConfidenceLevel;
  confidenceScore: number;
  confidenceReasoning: string;
  calibrationMetrics: CalibrationMetrics;
  simulatedScenarios?: {
    total: number;
    wins: number;
    avgMargin: string;
  };
  injuryReport?: Injury[];
  advancedAnalytics?: AdvancedMetric[];
  situationalIntelligence: SituationalIntelligence;
  eliteSignal179?: boolean;
  analysis: string;
  matchupHighlight?: string; 
  gameScript?: GameScriptPhase[];
  statComparison?: StatComparison[];
  trends?: string[];
  odds: {
    winner: string;
    loser: string;
  };
  props?: PropBet[];
}

export type ConfidenceFilterLevel = 'All' | ConfidenceLevel;
export type OddsFormat = 'American' | 'Decimal';

export interface UserSettings {
  preferredSport: string;
  defaultConfidenceFilter: ConfidenceFilterLevel;
  oddsFormat: OddsFormat;
}

export interface Sport {
    name: string;
    icon: React.FC<React.SVGProps<SVGSVGElement>>;
}

export interface ChatMessage {
  role: 'user' | 'model';
  content: Prediction | string;
}

export interface Game {
  id: string;
  homeTeam: string;
  awayTeam: string;
  league: string;
  time: string;
  date: string;
  status: 'Scheduled' | 'Live' | 'Finished';
  score?: string;
  odds?: GameOdds;
  isMustWin?: boolean;
  playoffImplications?: string;
  keyRosterNotes?: string;
}

import React, { memo, useState, useMemo } from 'react';
import type { Prediction, OddsFormat, PropBet } from '../types';
import { AnalyticsIcon, PlusIcon, CheckIcon, LogoIcon } from './Icons';

interface PredictionDisplayProps {
