    High: { bg: 'bg-green-950/20', text: 'text-green-400', border: 'border-green-500/30', accent: 'bg-green-500', glow: 'shadow-[0_0_30px_rgba(34,197,94,0.2)]' },
    Medium: { bg: 'bg-amber-950/20', text: 'text-amber-400', border: 'border-amber-500/30', accent: 'bg-amber-500', glow: 'shadow-[0_0_30px_rgba(245,158,11,0.2)]' },
    Low: { bg: 'bg-zinc-900/40', text: 'text-zinc-400', border: 'border-zinc-800', accent: 'bg-zinc-600', glow: 'shadow-none' },
