export const getSchedule = async (sport: string): Promise<Game[]> => {
  const ai = getAI();
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  const prompt = `Search for the MOST RECENT and ACTIVE ${sport} games occurring TODAY, ${today}. 
  CRITICAL: Extract LIVE MARKET ODDS (Spread, Moneyline, Total/O/U) from major sportsbooks. 
  Cross-reference current active rosters for late-breaking scratches.
  Include playoff context and situational urgency.
  Return STRICT JSON: { "games": [{ "id": "string", "homeTeam": "string", "awayTeam": "string", "league": "${sport}", "time": "string", "date": "Today", "status": "Scheduled|Live|Finished", "isMustWin": boolean, "playoffImplications": "string", "keyRosterNotes": "string (e.g. 'Star QB Questionable')", "odds": { "spread": "string (e.g. -3.5)", "moneyline": "string (e.g. -110 / +120)", "total": "string (e.g. 48.5)" } }] }`;

  const configWithSearch = { 
    tools: [{ googleSearch: {} }],
    temperature: 0.1,
    responseMimeType: 'application/json'
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: configWithSearch as any
    });
    const data = JSON.parse(response.text || '{}');
    return data.games || [];
  } catch (error: any) {
    return [];
  }
};

import React, { useState, useEffect, memo, useMemo, useCallback } from 'react';
import type { Game } from '../types';
import { getSchedule } from '../services/geminiService';

interface GameScheduleProps {
  sport: string;
  selectedGame: Game | null;
  onSelectGame: (game: Game) => void;
}

const LOAD_SUB_MESSAGES = [
  "Synchronizing High Fidelity Stakes...",
  "Auditing Market Liquidity...",
  "Scrubbing Active Roster Deltas...",
  "Verifying 179-Point Variance...",
  "Locking Elite Signal Feed..."
];

export const GameSchedule: React.FC<GameScheduleProps> = memo(({ sport, selectedGame, onSelectGame }) => {
  const [games, setGames] = useState<Game[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isRefreshing, setIsRefreshing] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [loadMsgIdx, setLoadMsgIdx] = useState(0);
  const [lastUpdated, setLastUpdated] = useState<Date>(new Date());

  const fetchGames = useCallback(async (quiet = false) => {
    if (!quiet) setIsLoading(true);
    else setIsRefreshing(true);

    setError(null);
    try {
      const fetchedGames = await getSchedule(sport);
      if (fetchedGames && fetchedGames.length > 0) {
        setGames(fetchedGames);
        setLastUpdated(new Date());
      } else if (!quiet) {
        setError(`No ${sport} matchups found for today.`);
      }
    } catch (err) {
      if (!quiet) setError('Network sync interrupted.');
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  }, [sport]);

  useEffect(() => { 
    fetchGames(); 
  }, [sport, fetchGames]);

  // Dynamic Polling Mechanism: Refresh odds/status every 90 seconds
  useEffect(() => {
    const pollInterval = setInterval(() => {
      fetchGames(true);
    }, 90000);
    return () => clearInterval(pollInterval);
  }, [fetchGames]);

  useEffect(() => {
    if (isLoading && games.length === 0) {
      const timer = setInterval(() => {
        setLoadMsgIdx((prev) => (prev + 1) % LOAD_SUB_MESSAGES.length);
      }, 1500);
      return () => clearInterval(timer);
    }
  }, [isLoading, games.length]);

  const sortedGames = useMemo(() => {
    return [...games].sort((a, b) => {
      const statusOrder = { 'Live': 0, 'Scheduled': 1, 'Finished': 2 };
      return (statusOrder[a.status] ?? 3) - (statusOrder[b.status] ?? 3);
    });
  }, [games]);

  if (isLoading && games.length === 0) {
    return (
      <div className="py-24 flex flex-col items-center justify-center space-y-6">
        <div className="relative w-16 h-16">
          <div className="absolute inset-0 border-4 border-amber-500/10 rounded-full"></div>
          <div className="absolute inset-0 border-4 border-t-amber-500 rounded-full animate-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-2 h-2 bg-amber-500 rounded-full animate-pulse shadow-[0_0_15px_rgba(245,158,11,0.8)]"></div>
          </div>
        </div>
        <div className="text-center space-y-2">
          <div className="text-zinc-500 font-black uppercase text-[10px] tracking-[0.4em] animate-pulse">
            High Fidelity Sync
          </div>
          <div className="text-amber-500 font-black uppercase text-[11px] tracking-widest min-h-[1.5rem]">
            {LOAD_SUB_MESSAGES[loadMsgIdx]}
          </div>
        </div>
      </div>
    );
  }

  if (error) return (
    <div className="py-20 text-center space-y-4">
        <div className="text-red-500/70 font-black uppercase text-[10px] tracking-widest">{error}</div>
        <button onClick={() => fetchGames()} className="text-[9px] font-black text-zinc-500 hover:text-white uppercase tracking-widest border border-zinc-800 px-4 py-2 rounded-full transition-all">Retry Sync</button>
    </div>
  );

  return (
    <div className="space-y-4 w-full animate-fade-in">
      <div className="flex justify-between items-center px-2">
          <div className="flex items-center gap-2">
              <span className={`w-1.5 h-1.5 rounded-full ${isRefreshing ? 'bg-amber-500 animate-ping' : 'bg-green-500'}`}></span>
              <span className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">
                  Live Feed • {lastUpdated.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </span>
          </div>
          <button onClick={() => fetchGames(true)} disabled={isRefreshing} className="text-[8px] font-black text-amber-500/50 hover:text-amber-500 uppercase tracking-widest transition-colors disabled:opacity-30">
              {isRefreshing ? 'Syncing...' : 'Force Refresh'}
          </button>
      </div>

      <div className="grid gap-3 max-h-[450px] overflow-y-auto pr-2 custom-scrollbar">
        {sortedGames.map((game) => {
          const isSelected = selectedGame?.id === game.id;
          const isLive = game.status === 'Live';

          return (
            <button
              key={game.id}
              onClick={() => onSelectGame(game)}
              className={`relative group w-full text-left p-5 rounded-3xl border-2 transition-all duration-500 ${
                isSelected
                  ? 'bg-zinc-900 border-amber-500/50 shadow-[0_0_40px_rgba(245,158,11,0.1)]'
                  : 'bg-zinc-950/50 border-zinc-900 hover:border-zinc-800 hover:bg-zinc-900/60'
              }`}
            >
              {game.isMustWin && (
                <span className="absolute -top-[2px] right-8 px-4 py-1 rounded-b-xl bg-amber-500 text-black text-[9px] font-black uppercase tracking-widest z-10 animate-pulse shadow-xl">
                    High Stakes
                </span>
              )}

              <div className="flex items-center justify-between gap-6 mb-4">
                <div className="flex-1 flex flex-col items-center gap-2">
                    <img src={`https://avatar.vercel.sh/${encodeURIComponent(game.homeTeam)}.png?size=80`} className={`w-14 h-14 rounded-full border-2 transition-transform duration-500 group-hover:scale-105 ${isSelected ? 'border-amber-500' : 'border-zinc-800'}`} />
                    <span className={`text-[10px] font-black uppercase tracking-tighter text-center ${isSelected ? 'text-white' : 'text-zinc-500'}`}>{game.homeTeam}</span>
                </div>

                <div className="flex flex-col items-center justify-center min-w-[120px]">
                   <div className={`px-4 py-1.5 rounded-full border flex items-center gap-2 mb-2 ${isLive ? 'bg-red-500/10 border-red-500/30' : 'bg-zinc-900/80 border-zinc-800'}`}>
                        <div className={`w-1.5 h-1.5 rounded-full ${isLive ? 'bg-red-500 animate-pulse' : 'bg-amber-500'}`}></div>
                        <span className={`text-[10px] font-black uppercase tracking-widest ${isLive ? 'text-red-500' : 'text-white'}`}>
                            {isLive ? 'LIVE' : game.time}
                        </span>
                   </div>
                   {game.keyRosterNotes && (
                       <div className="text-[8px] font-bold text-zinc-600 uppercase mt-1 text-center max-w-[100px] leading-tight opacity-70 italic">
                            {game.keyRosterNotes}
                       </div>
                   )}
                </div>

                <div className="flex-1 flex flex-col items-center gap-2">
                    <img src={`https://avatar.vercel.sh/${encodeURIComponent(game.awayTeam)}.png?size=80`} className={`w-14 h-14 rounded-full border-2 transition-transform duration-500 group-hover:scale-105 ${isSelected ? 'border-amber-500' : 'border-zinc-800'}`} />
                    <span className={`text-[10px] font-black uppercase tracking-tighter text-center ${isSelected ? 'text-white' : 'text-zinc-500'}`}>{game.awayTeam}</span>
                </div>
              </div>

              {/* Live Odds Feed Strip */}
              <div className={`grid grid-cols-3 gap-1 mt-2 p-2 rounded-2xl bg-black/40 border transition-colors ${isSelected ? 'border-amber-500/20' : 'border-white/5'}`}>
                  <div className="flex flex-col items-center">
                      <span className="text-[7px] font-black text-zinc-600 uppercase mb-0.5">Spread</span>
                      <span className="text-[10px] font-black text-white tabular-nums tracking-tighter">{game.odds?.spread || 'N/A'}</span>
                  </div>
                  <div className="flex flex-col items-center border-x border-white/5">
                      <span className="text-[7px] font-black text-zinc-600 uppercase mb-0.5">MLine</span>
                      <span className="text-[10px] font-black text-amber-500 tabular-nums tracking-tighter">{game.odds?.moneyline || 'N/A'}</span>
                  </div>
                  <div className="flex flex-col items-center">
                      <span className="text-[7px] font-black text-zinc-600 uppercase mb-0.5">Total</span>
                      <span className="text-[10px] font-black text-white tabular-nums tracking-tighter">{game.odds?.total || 'N/A'}</span>
                  </div>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
});

